// STOP-NONACP r3.1: the data behind stop-gate.rules.test.ts. See stop-gate.rules.checker.ts for what each rule means.
//
// One EngineRules per scanned file. Everything the checker does not accept as written is listed here, by function key, with a reason:
//   fns[].kind     turn (a turn-path function that keeps bare sites), not-turn (catalog, create time, interruptTurn, stopAll, dispose), close (a live
//                  close or stop handler, or a continuation that must finish despite a mark), reap (cleanup after the ending)
//   fns[].awaits / chains / detached / emits / launches / calls / refs
//                  exempt sites [ordinal, text, reason?]: ordinal = 1-based index of that kind in the function, text = fingerprint of the item.
//                  A site that no longer matches (moved, edited, a new item before it) is red, and so is an item without a site.
//   cleanup        the functions allowed to call gate.cleanupStep (a stop or close continuation)
//   fixtures       every gate wrapper on the turn path (MS1): the test drops each one and expects R1 red
// Adding an engine: add it to SCANNED in the test, to ENGINES here and to APPLIES in the test; run `node server/drivers/stop-gate.rules.print.ts <id>`
// from the repo root for a draft of the rows the checker asks for, read each one, give it a real reason, and do not leave TODO.
// PENDING_ENGINES lists engines that are scanned and reported but not enforced yet; the test fails if a pending engine is already clean.
export const ROW_KINDS = ["await", "chain", "detached", "emit", "launch", "call", "ref"] as const;
export type RowKind = (typeof ROW_KINDS)[number];

/** [ordinal, operand text, reason]. Ordinal: 1-based among the items of that kind in the function (nested functions excluded). */
export type Row = [ordinal: number, text: string, reason?: string];

export type FnKind = "turn" | "not-turn" | "close" | "reap";

export interface FnRule {
  /** `codex>create>sendTurn>launchAttempt`; anonymous callbacks `>#n` */
  key: string;
  /** turn: a turn-path function that keeps bare sites (each row has its own reason). not-turn: catalog / create-time / interruptTurn / stopAll / dispose.
   *  close: a live close or stop handler after launch. reap: cleanup after the ending. */
  kind: FnKind;
  reason: string;
  awaits?: Row[];
  chains?: Row[];
  detached?: Row[];
  emits?: Row[];
  launches?: Row[];
  calls?: Row[];
  refs?: Row[];
}

/** MS1: one gate wrapper on the turn path. The test asserts the await at `key` #`ordinal` is `await gate.<wrapper>(e, <operand>)` in a turn-path function,
 *  and that dropping the wrapper makes the checker red at that site. `operand` is the fingerprint of the wrapped promise expression. */
export interface Fixture {
  key: string;
  ordinal: number;
  wrapper: "step" | "cleanupStep";
  operand: string;
}

export interface EngineRules {
  /** the key prefix and the name in diagnostics */
  id: string;
  /** repo-relative */
  file: string;
  /** callee texts that emit events to listeners */
  emitters: string[];
  /** extra import names that are launch primitives (on top of DEFAULT_PRIMITIVE_IMPORTS) */
  primitiveImports?: string[];
  /** helper names called as request(method, ...) whose method decides whether the call is a launch */
  requestFns?: string[];
  /** functions allowed to call gate.cleanupStep */
  cleanup: string[];
  fns: FnRule[];
  fixtures: Fixture[];
  /** a draft: the lists below are not filled in yet (engine not merged) */
  todo?: string;
}

export const ENDING = ["turn.completed", "turn.started"];
export const LAUNCH_METHODS = ["turn/start", "review/start", "thread/compact/start"];
export const DEFAULT_PRIMITIVE_IMPORTS = ["spawnCli", "execCli", "spawn", "spawnSync", "exec", "execSync", "execFile", "execFileSync", "fork"];

/** Engines whose file is scanned and reported but not yet enforced. Empty: all seven engines are enforced. */
export const PENDING_ENGINES: string[] = [];


